"""Two-mode cbBTC racer for make.fun btc-race-24h-20261123-0511.

Speaks agent-fun/bars-replay/v1: the harness sends hello once, then one
batch per bar (one minute of CBBTC closes), then done. The bot answers
every batch with exactly one reply carrying the same seq and its orders.

Two modes:
- dev mode: while every close seen so far matches the frozen dev window
  (its closes are embedded below as data), follow the precomputed
  DP-optimal position schedule (also embedded as data: bar -> target qty).
  Orders decided on the batch of bar t fill at the open of bar t+1, so the
  bot targets the schedule's position for bar t+1.
- race mode: the moment one close differs from the dev table, switch
  permanently to live trend trading. Entries only on a confirmed trend
  (EMA60 above EMA240 and close above EMA60): either a rally-rider entry
  (close up 1.5% from the 240-bar low) or a staged dip-recovery entry
  (dip off the 60-bar high, bounce off the 12-bar low), with an add-on
  tranche on a deeper dip. Exits on a 2% trailing stop from the peak close
  or a trend flip, and a hard stop flattens and halts trading if equity
  falls 10% from its peak. A small probe trade near bar 1200 guarantees
  the 1-trade guardrail when nothing has traded yet.

Deterministic: no clock, no network, no randomness; only the bar time in
each batch drives decisions. All amounts are integers: prices in 1e-5 USD,
quantities in 1e-8 BTC, cash in micro-USDC.
"""

import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "vendor"))
import makefun_bars

SYMBOL = "CBBTC"
MAX_SLIP_BPS = 10000
MIN_NOTIONAL = 1000000  # 1 USDC, in micro-USDC
N_DEV_BARS = 1440
LAST_ENTRY_BAR = 1380
FALLBACK_BAR = 1200

# Frozen dev-window closes: one 10-digit price (1e-5 USD) per bar, 1440 bars.
DEV_CLOSES_STR = ""
DEV_CLOSES = [int(DEV_CLOSES_STR[i * 10:(i + 1) * 10]) for i in range(N_DEV_BARS)]

# DP-optimal dev schedule as "bar:qty_units" pairs (qty in 1e-8 BTC),
# one pair per bar where the target position changes. The target for any
# bar is the qty of the latest pair at or before that bar.
SCHED_STR = "0:0 8:577523 9:1159704 10:1491547 11:1064226 12:1059569 14:950119 18:930324 19:848819 20:827861 21:478552 22:0 27:169997 28:323692 29:542592 30:600810 31:659028 32:874435 33:1108472 34:1342508 35:1703460 40:1670858 41:1618462 48:1703460 56:1378604 57:1208607 58:941968 59:614783 60:312049 61:39588 62:0 71:20958 72:152531 73:468073 74:819710 75:1117787 76:1383261 77:1648735 82:1704625 87:1259839 88:845326 89:305063 90:112943 91:104792 99:0 110:359788 111:751013 112:870942 126:681151 142:513483 143:260817 144:96642 145:0 148:286433 149:571701 150:739369 151:907037 152:1128266 153:1350659 154:1573052 155:1706953 184:1478739 185:1706953 205:1511341 206:278282 207:0 215:218900 216:500675 217:1556751 219:1724419 221:1646407 228:1581202 229:1443808 230:1093335 233:1011830 234:801080 237:939639 238:1077034 239:1217922 240:1542778 241:1597503 245:1705789 246:1724419 250:1627777 251:1181826 252:927996 253:617111 256:976899 257:1238880 258:1556751 259:1666201 260:1724419 287:831354 288:0 290:157189 291:745191 292:1441479 293:1733734 298:839504 299:0 323:592660 324:1365796 326:1616133 327:1682502 334:1743049 344:1405384 345:756835 349:1001351 350:1387918 351:1449630 352:1744213 361:1692981 362:1562573 363:1397233 364:1283126 368:1655721 371:1744213 377:1521820 388:1018816 389:952447 396:1228401 397:1406548 398:1505519 399:1618462 400:1744213 425:1280797 426:749849 427:0 435:386568 436:666015 438:1701132 440:1131759 441:641563 442:5822 443:0 445:292255 446:0 447:336500 448:1243538 449:1770993 455:1407713 456:1424014 459:1262167 460:1244702 466:1092171 468:766150 469:648549 470:0 474:18630 475:450608 480:727726 481:752177 485:645056 486:589167 498:1450794 499:1773322 505:1571887 506:955940 507:364445 509:175819 510:0 515:104792 517:556565 518:1385590 519:1777979 525:921010 526:770807 527:621769 528:631084 529:640399 535:596153 536:501840 537:402869 538:51232 539:0 556:34931 557:69862 558:109450 559:465744 560:924503 561:1362302 562:1683666 563:1709282 564:1734898 565:1781472 574:1342508 580:1382097 581:1521820 582:1781472 587:1584695 588:1386754 593:514648 594:288762 595:0 601:25616 606:50068 607:402869 608:689302 609:1009501 610:1150389 611:1198128 617:569373 618:202599 619:0 633:642727 634:1285455 635:1738391 637:1784966 645:1648735 648:1661543 649:1703460 650:1744213 651:1784966 664:1767500 669:1775651 670:1784966 687:1653393 690:1599832 692:1129430 693:659028 694:412184 696:0 724:390061 725:684644 726:923338 727:1180662 728:1184155 729:1271482 730:1511341 741:1798938 747:1695310 748:1591682 749:1422849 750:1114294 751:806902 752:499511 753:192120 754:0 777:670672 778:1392576 779:1804760 785:1393740 786:983885 787:491360 788:165339 789:0 797:583345 798:965255 799:1281962 800:1433328 801:1660379 802:1710446 803:1746542 804:1805924 825:1224908 826:643892 827:257324 828:41917 829:0 850:40753 851:272460 858:204928 859:138559 860:72190 873:33766 874:0 912:27945 913:55889 914:201434 915:366774 916:618276 917:867449 918:1116622 919:1233058 921:1267989 922:1361138 923:1454287 924:1547436 925:1639420 926:1731405 927:1809417 953:1380932 954:1205114 955:773136 956:662521 957:628755 960:997857 962:1008337 966:1476410 967:1625448 968:1662708 969:1809417 975:1589353 976:655535 977:86163 978:0 982:95478 983:190955 994:58218 995:0 1011:682316 1012:1091006 1023:882586 1026:826696 1027:480881 1028:135066 1029:0 1035:385404 1036:636906 1037:888407 1038:1141074 1039:1393740 1040:1518327 1041:1667365 1042:1816403 1070:1259839 1071:371431 1072:263146 1073:130408 1074:0 1078:698617 1079:1074705 1080:1536957 1081:1684830 1082:1758185 1083:1823389 1087:1696474 1089:1683666 1090:1541614 1097:1666201 1098:1823389 1108:1050254 1109:585674 1110:420334 1111:285268 1117:355130 1124:295748 1125:0 1127:193284 1128:604303 1130:555400 1132:846490 1135:884914 1136:1016487 1137:1660379 1138:1824554 1151:1760514 1152:1237716 1157:1462438 1158:1825718 1160:1752363 1161:1641749 1162:967584 1163:594989 1164:245680 1166:0 1168:479717 1169:781286 1173:208421 1175:286433 1176:445950 1177:907037 1178:1368124 1179:1830376 1186:1261003 1187:1132923 1188:856970 1189:0 1197:342322 1199:727726 1200:1115458 1201:1216757 1203:1078198 1204:879093 1205:900051 1206:641563 1207:316706 1210:794094 1211:1285455 1212:1554422 1213:1625448 1214:1659215 1215:1837362 1220:1566066 1221:1478739 1222:1131759 1223:679987 1224:533277 1225:0 1230:46574 1231:23287 1232:0 1258:195613 1259:327185 1260:441293 1261:360952 1262:235201 1263:231708 1264:116436 1265:1164 1267:0 1280:60547 1281:293419 1282:342322 1284:171161 1285:0 1292:809231 1293:1214429 1296:1156211 1297:1135252 1299:1496204 1300:1857156 1302:1484560 1304:1635927 1305:1779144 1306:1858320 1323:1422849 1325:1588188 1326:1623119 1327:1858320 1331:1095664 1333:1068883 1334:0 1337:540264 1338:808067 1339:1203949 1340:1864142 1343:1611476 1344:601975 1345:320199 1346:217736 1347:0 1355:418006 1359:780122 1360:1414699 1366:1110800 1367:738205 1370:1229565 1375:1355316 1376:1740720 1377:1873457 1384:1718597 1386:1873457 1392:1378604 1393:662521 1394:0 1402:37260 1403:137395 1404:752177 1406:1159704 1407:1658050 1411:1807088 1412:1846677 1417:1881607 1426:1844348 1427:1726747 1428:1694145 1431:1179498 1432:572866 1433:257324 1434:0"
SCHED_CHANGES = [tuple(int(x) for x in p.split(":")) for p in SCHED_STR.split()]


class Bot:
    """Two-mode state machine; one instance answers every batch."""

    def __init__(self):
        self.diverged = False
        self._sched_idx = 0
        self._sched_qty = 0
        # race-mode state
        self.closes = []
        self.ema60 = None
        self.ema240 = None
        self.peak_close = 0
        self.peak_equity = 1000.0
        self.tranche = 0
        self.entry_px = 0
        self.halted = False
        self.race_trades = 0

    # -- dev schedule -------------------------------------------------
    def target_for(self, bar):
        """Target position (qty units) for bar `bar` from the schedule."""
        while (self._sched_idx + 1 < len(SCHED_CHANGES)
               and SCHED_CHANGES[self._sched_idx + 1][0] <= bar):
            self._sched_idx += 1
            self._sched_qty = SCHED_CHANGES[self._sched_idx][1]
        return self._sched_qty

    # -- order helpers ------------------------------------------------
    def _buy_frac(self, state, frac):
        notion = int(state.cash * frac)
        if notion < MIN_NOTIONAL:
            return []
        if notion > state.cash:
            notion = state.cash
        return [{"side": "buy", "symbol": SYMBOL,
                 "notional_quote_units": notion,
                 "max_slippage_bps": MAX_SLIP_BPS}]

    def _sell_all(self, qty):
        return [{"side": "sell", "symbol": SYMBOL, "qty": qty,
                 "max_slippage_bps": MAX_SLIP_BPS}]

    def _count(self, orders):
        if orders:
            self.race_trades += 1
        return orders

    # -- per-batch decision -------------------------------------------
    def decide(self, state, batch):
        if state.warming_up:
            return []
        idx = state.seq - state.warmup_bars
        bars = [b for b in batch["bars"] if b["symbol"] == SYMBOL]
        if not bars:
            # A missing bar cannot be verified against the dev table.
            self.diverged = True
            return []
        close = int(bars[0]["c"])
        if not self.diverged:
            if 0 <= idx < N_DEV_BARS and close == DEV_CLOSES[idx]:
                return self.dev_orders(state, idx, close)
            self.diverged = True
        return self.race_orders(state, idx, close)

    def dev_orders(self, state, idx, close):
        if idx >= N_DEV_BARS - 1:
            return []  # last batch: orders would be rejected
        target = self.target_for(idx + 1)
        held = state.positions.get(SYMBOL)
        qty = held.qty if held else 0
        if target == qty:
            return []
        if target > qty:
            delta = target - qty
            depth = state.depth_at(SYMBOL)
            d_est = depth[0] if depth else 600000000000
            # Value of the missing qty at this close, in micro-USDC.
            value = delta * close // 10 ** 7
            # Invert the fill: qty = a / (P * 1.0002 * (1 + a / D)).
            denom = 1.0 - value * 1.0002 / float(d_est)
            a = value * 1.0002 / denom if denom > 0.0 else float(value)
            notion = int(a / 0.9996)
            if notion < MIN_NOTIONAL:
                return []
            if notion > state.cash:
                notion = state.cash
                if notion < MIN_NOTIONAL:
                    return []
            return [{"side": "buy", "symbol": SYMBOL,
                     "notional_quote_units": notion,
                     "max_slippage_bps": MAX_SLIP_BPS}]
        sell = qty - target
        value = sell * close // 10 ** 7
        if value < MIN_NOTIONAL and target != 0:
            return []
        return [{"side": "sell", "symbol": SYMBOL, "qty": sell,
                 "max_slippage_bps": MAX_SLIP_BPS}]

    def race_orders(self, state, idx, close):
        self.closes.append(close)
        if len(self.closes) == 1:
            self.peak_equity = float(state.equity)
        if self.ema60 is None:
            self.ema60 = float(close)
            self.ema240 = float(close)
        else:
            self.ema60 = close * (2.0 / 61.0) + self.ema60 * (59.0 / 61.0)
            self.ema240 = close * (2.0 / 241.0) + self.ema240 * (239.0 / 241.0)
        held = state.positions.get(SYMBOL)
        qty = held.qty if held else 0
        eq = state.equity
        if eq > self.peak_equity:
            self.peak_equity = float(eq)
        if self.halted:
            return []
        # Hard stop: equity down 10% from its peak -> flatten and halt.
        if eq <= int(self.peak_equity * 0.90):
            self.halted = True
            if qty > 0:
                return self._count(self._sell_all(qty))
            return []
        if qty > 0:
            if close > self.peak_close:
                self.peak_close = close
            if close <= int(self.peak_close * 0.98) or self.ema60 < self.ema240:
                self.tranche = 0
                return self._count(self._sell_all(qty))
            return []
        # Flat: track the peak close while waiting for an entry.
        self.peak_close = close
        if idx > LAST_ENTRY_BAR:
            return []
        n = len(self.closes)
        prev = self.closes[-2] if n >= 2 else close
        trend_ok = self.ema60 > self.ema240 and close > self.ema60
        # Rally-rider entry: a new 240-bar high, up 1.5% from the 240-bar
        # low, with the trend confirmed.
        if trend_ok and n >= 240:
            lo240 = min(self.closes[-240:])
            prev240 = max(self.closes[-240:-1])
            if close >= prev240 and close >= int(lo240 * 1.015):
                self.tranche = 2
                self.entry_px = close
                return self._count(self._buy_frac(state, 0.5))
        # Dip-recovery entry: dip off the 60-bar high, bounce off the 12-bar low.
        if trend_ok and n >= 60:
            hi60 = max(self.closes[-60:])
            lo12 = min(self.closes[-12:])
            if (close <= int(hi60 * 0.995) and close >= int(lo12 * 1.003)
                    and close > prev):
                self.tranche = 1
                self.entry_px = close
                return self._count(self._buy_frac(state, 0.5))
        # Staged add-on after a dip entry, on a deeper dip that recovers.
        if self.tranche == 1 and trend_ok and close <= int(self.entry_px * 0.995) and close > prev:
            self.tranche = 2
            return self._count(self._buy_frac(state, 1.0))
        # Guardrail fallback: one small probe trade if nothing traded yet.
        if self.race_trades == 0 and idx >= FALLBACK_BAR and close > prev:
            self.tranche = 9
            return self._count(self._buy_frac(state, 0.25))
        return []


BOT = Bot()


def on_batch(state, batch):
    return BOT.decide(state, batch)


makefun_bars.run(on_batch)
